{"content":"#!/usr/bin/env python3
"""Search for constant bits in linear combinations of P/C halves for fixed key."""
import random, sys
sys.path.insert(0, '/app')
from feal import encrypt, set_keys, getleft, getright

def main():
    random.seed(7)
    k = [random.getrandbits(20) for _ in range(4)]
    keys = set_keys(*k)
    print("key seeds:", [hex(x) for x in k])
    n = 50000
    # combos: mask over 4 halves [PL,PR,CL,CR]
    # We'll accumulate counts per (combo, bit) of when bit=1
    bitcount = [[0]*32 for _ in range(16)]
    for _ in range(n):
        P = random.getrandbits(64)
        C = encrypt(P, keys)
        halves = [getleft(P), getright(P), getleft(C), getright(C)]
        for combo in range(16):
            val = 0
            for i in range(4):
                if combo & (1<<i):
                    val ^= halves[i]
            for b in range(32):
                if (val >> b) & 1:
                    bitcount[combo][b] += 1
    names = ['PL','PR','CL','CR']
    print("Combos with |Pr(bit=1)-0.5| > 0.15:")
    for combo in range(16):
        cname = ''.join(names[i] for i in range(4) if combo & (1<<i)) or 'ZERO'
        for b in range(32):
            p = bitcount[combo][b]/n
            if abs(p-0.5) > 0.15:
                print(f"  {cname} bit {b}: Pr=1 {p:.4f} bias={abs(p-0.5):.4f}")
    print("done")

if __name__ == '__main__':
    main()
